/** Source-file information, separate from output engine settings. Optional reads never alter playback. */
@androidx.annotation.OptIn(markerClass=androidx.media3.common.util.UnstableApi.class)
final class SongInfo {
    private static final ThreadPoolExecutor WORKER=new ThreadPoolExecutor(1,1,0,TimeUnit.MILLISECONDS,new LinkedBlockingQueue<>(2),new ThreadPoolExecutor.DiscardOldestPolicy());
    static final class Info {final LinkedHashMap<String,String> rows=new LinkedHashMap<>();void put(String label,Object value){String s=value==null?"":value.toString().trim();if(!s.isEmpty())rows.put(label,s);}}
    static Info base(Track track){Info i=new Info();i.put("제목",track.title);i.put("아티스트",track.artist);i.put("앨범",track.album);i.put("장르",track.genre);if(track.trackNumber>0)i.put("트랙 번호",track.trackNumber);if(track.discNumber>0)i.put("디스크 번호",track.discNumber);if(track.duration>0)i.put("재생 시간",duration(track.duration));i.put("저장소",track.sourceLabel());i.put("폴더",track.folder);i.put("파일 이름",Uri.parse(track.uri).getLastPathSegment());i.put("파일 주소",track.uri);return i;}
    static String duration(long ms){long s=ms/1000;return String.format(Locale.getDefault(),"%d:%02d:%02d",s/3600,s/60%60,s%60);}
    static Info read(Context c,Track track)throws Exception{return read(c,track,track.drive()?new DriveHttp(DriveAuth.get(c)):null);}
    static Info read(Context c,Track track,DriveHttp http)throws Exception{
        Info info=base(track);Uri uri=Uri.parse(track.uri);MediaDataSource source=null;long size=-1;
        File offline=track.drive()?OfflineMusic.available(c,track.uri):null;if(offline!=null){size=offline.length();source=new LocalSource(c,Uri.fromFile(offline));info.put("오프라인 보관","이 기기에 보관됨");}
        else if(track.drive()){if(!DriveAuth.get(c).accountId().equals(uri.getAuthority()))throw new IOException("Google Drive 계정을 확인해 주세요.");size=DriveLibrary.fileSize(c,track.uri);source=new DriveMetadata(http,uri,size);}
        else{if("file".equals(uri.getScheme()))size=new File(uri.getPath()).length();else try(var cursor=c.getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME,OpenableColumns.SIZE},null,null,null)){if(cursor!=null&&cursor.moveToFirst()){info.put("파일 이름",cursor.getString(0));if(!cursor.isNull(1))size=cursor.getLong(1);}}catch(Exception optional){}try{source=new LocalSource(c,uri);}catch(Exception optional){}}
        if(size>=0)info.put("파일 크기",String.format(Locale.getDefault(),"%,d 바이트 · %.2f MiB",size,size/1048576.0));
        try{
            MediaMetadataRetriever retriever=new MediaMetadataRetriever();try{if(source!=null)retriever.setDataSource(new Borrowed(source));else retriever.setDataSource(c,uri);int[] keys={MediaMetadataRetriever.METADATA_KEY_TITLE,MediaMetadataRetriever.METADATA_KEY_ARTIST,MediaMetadataRetriever.METADATA_KEY_ALBUM,MediaMetadataRetriever.METADATA_KEY_ALBUMARTIST,MediaMetadataRetriever.METADATA_KEY_GENRE,MediaMetadataRetriever.METADATA_KEY_YEAR,MediaMetadataRetriever.METADATA_KEY_COMPOSER,MediaMetadataRetriever.METADATA_KEY_CD_TRACK_NUMBER,MediaMetadataRetriever.METADATA_KEY_DISC_NUMBER};String[] labels={"제목","아티스트","앨범","앨범 아티스트","장르","연도","작곡가","트랙 번호","디스크 번호"};for(int n=0;n<keys.length;n++)info.put(labels[n],retriever.extractMetadata(keys[n]));String length=retriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION);if(length!=null)info.put("재생 시간",duration(Long.parseLong(length)));String bitrate=retriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_BITRATE);if(bitrate!=null)info.put("비트레이트",String.format(Locale.getDefault(),"%,d kbps",Long.parseLong(bitrate)/1000));if(Build.VERSION.SDK_INT>=31){String rate=retriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_SAMPLERATE),bits=retriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_BITS_PER_SAMPLE);if(rate!=null&&!rate.equals("0"))info.put("샘플레이트",rate+" Hz");if(bits!=null&&!bits.equals("0"))info.put("비트 깊이",bits+" bit");}}catch(Exception optionalTags){}finally{retriever.release();}
            if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();MediaExtractor extractor=new MediaExtractor();try{if(source!=null)extractor.setDataSource(new Borrowed(source));else extractor.setDataSource(c,uri,null);for(int n=0;n<extractor.getTrackCount();n++){MediaFormat format=extractor.getTrackFormat(n);String mime=format.getString(MediaFormat.KEY_MIME);if(mime==null||!mime.startsWith("audio/"))continue;info.put("코덱",mime);if(format.containsKey(MediaFormat.KEY_SAMPLE_RATE))info.put("샘플레이트",String.format(Locale.getDefault(),"%,d Hz",format.getInteger(MediaFormat.KEY_SAMPLE_RATE)));if(format.containsKey(MediaFormat.KEY_CHANNEL_COUNT))info.put("채널",format.getInteger(MediaFormat.KEY_CHANNEL_COUNT)+"채널");if(format.containsKey("bits-per-sample"))info.put("비트 깊이",format.getInteger("bits-per-sample")+" bit");break;}}catch(Exception optionalFormat){}finally{extractor.release();}
            if(source!=null){byte[] head=new byte[65536];try{int got=source.readAt(0,head,0,(int)Math.min(head.length,source.getSize()));header(info,head,got);}catch(Exception optionalHeader){}}
            if(!info.rows.containsKey("코덱"))info.put("코덱",!track.kind.isEmpty()?track.kind.toUpperCase(Locale.ROOT):!track.mime.isEmpty()?track.mime:"확인할 수 없음");if(java.util.Set.of("audio/mpeg","audio/mp4a-latm","audio/opus","audio/vorbis").contains(info.rows.get("코덱")))info.put("비트 깊이","해당 없음 · 손실 압축");for(String key:new String[]{"샘플레이트","비트 깊이","채널"})if(!info.rows.containsKey(key))info.put(key,"확인할 수 없음");
            return info;
        }finally{if(source!=null)source.close();}
    }
    static void header(Info info,byte[] b,int n){if(n>=42&&b[0]=='f'&&b[1]=='L'&&b[2]=='a'&&b[3]=='C'&&(b[4]&127)==0){info.put("코덱","audio/flac");int rate=((b[18]&255)<<12)|((b[19]&255)<<4)|((b[20]&255)>>4),channels=((b[20]>>1)&7)+1,bits=(((b[20]&1)<<4)|((b[21]&255)>>4))+1;info.put("샘플레이트",String.format(Locale.getDefault(),"%,d Hz",rate));info.put("비트 깊이",bits+" bit");info.put("채널",channels+"채널");}else if(n>=12&&b[0]=='R'&&b[1]=='I'&&b[8]=='W'&&b[9]=='A'){info.put("코덱","audio/wav");for(int at=12;at+8<=n;){long length=le(b,at+4,4);if(b[at]=='f'&&b[at+1]=='m'&&b[at+2]=='t'&&length>=16&&at+24<=n){int format=(int)le(b,at+8,2);info.put("채널",le(b,at+10,2)+"채널");info.put("샘플레이트",String.format(Locale.getDefault(),"%,d Hz",le(b,at+12,4)));if(format==1||format==3||format==65534)info.put("비트 깊이",(format==65534&&length>=40&&at+28<=n&&le(b,at+26,2)>0?le(b,at+26,2):le(b,at+22,2))+" bit");break;}long next=at+8+length+(length&1);if(next>n||next<=at)break;at=(int)next;}}else if(n>=80&&b[0]=='D'&&b[1]=='S'&&b[2]=='D'&&b[28]=='f'&&b[29]=='m'){info.put("코덱","DSD / DSF");info.put("샘플레이트",String.format(Locale.getDefault(),"%,d Hz",le(b,56,4)));info.put("채널",le(b,52,4)+"채널");info.put("비트 깊이","1 bit DSD");}}
    private static long le(byte[] b,int at,int count){long v=0;for(int n=0;n<count;n++)v|=(long)(b[at+n]&255)<<(8*n);return v;}
    static void show(Activity a,Track track){LinearLayout body=new LinearLayout(a);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(Ui.dp(a,20),Ui.dp(a,8),Ui.dp(a,20),Ui.dp(a,16));ScrollView scroll=new ScrollView(a);scroll.addView(body);Info initial=base(track);fill(a,body,initial,"파일 정보를 읽고 있습니다…");var dialog=new androidx.appcompat.app.AlertDialog.Builder(a).setTitle("곡 정보").setView(scroll).setPositiveButton("닫기",null).setNeutralButton("정보 복사",null).create();Info[] displayed={initial};dialog.setOnShowListener(ignored->dialog.getButton(DialogInterface.BUTTON_NEUTRAL).setOnClickListener(v->{StringBuilder text=new StringBuilder();displayed[0].rows.forEach((label,value)->text.append(label).append(": ").append(value).append('\n'));a.getSystemService(ClipboardManager.class).setPrimaryClip(ClipData.newPlainText("곡 정보",text));Toast.makeText(a,"곡 정보를 복사했습니다.",Toast.LENGTH_SHORT).show();}));dialog.show();Context app=a.getApplicationContext();Future<?> task=WORKER.submit(()->{Info info;String status="음원 파일 기준 정보입니다. 출력 설정과 다를 수 있습니다.";try{info=read(app,track);}catch(Exception e){info=base(track);status="파일의 상세 정보를 읽지 못했습니다. 저장된 곡 정보를 표시합니다.";}Info ready=info;String message=status;a.runOnUiThread(()->{if(a.isDestroyed()||!dialog.isShowing())return;displayed[0]=ready;fill(a,body,ready,message);});});dialog.setOnDismissListener(ignored->task.cancel(true));}
    private static void fill(Activity a,LinearLayout body,Info info,String status){
        body.removeAllViews();TextView title=Ui.text(a,info.rows.getOrDefault("제목","제목 없는 곡"),20,Ui.INK);Ui.lines(title,2);body.addView(title);TextView subtitle=Ui.text(a,info.rows.getOrDefault("아티스트","")+" · "+info.rows.getOrDefault("앨범",""),12,Ui.MUTED);subtitle.setPadding(0,Ui.dp(a,8),0,Ui.dp(a,14));Ui.lines(subtitle,2);body.addView(subtitle);
        String[] specs={"코덱","샘플레이트","비트 깊이","채널","비트레이트","재생 시간"};for(int row=0;row<specs.length;row+=2){LinearLayout pair=new LinearLayout(a);for(int col=0;col<2;col++){String key=specs[row+col];LinearLayout card=infoCell(a,key,info.rows.getOrDefault(key,"확인 중"),true);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(col==0?0:Ui.dp(a,4),Ui.dp(a,6),col==0?Ui.dp(a,4):0,0);pair.addView(card,lp);}body.addView(pair);}
        for(String key:new String[]{"장르","앨범 아티스트","연도","작곡가","트랙 번호","디스크 번호","파일 크기","저장소","폴더","파일 이름","파일 주소"})if(info.rows.containsKey(key)){LinearLayout item=infoCell(a,key,info.rows.get(key),false);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=Ui.dp(a,6);body.addView(item,lp);}TextView hint=Ui.text(a,status,11,Ui.MUTED);hint.setPadding(0,Ui.dp(a,18),0,0);hint.setTag("song-info-status");body.addView(hint);
    }
    private static LinearLayout infoCell(Activity a,String key,String content,boolean spec){LinearLayout item=new LinearLayout(a);item.setOrientation(LinearLayout.VERTICAL);item.setPadding(Ui.dp(a,12),Ui.dp(a,11),Ui.dp(a,12),Ui.dp(a,11));item.setBackground(Ui.flatSurface(a,spec?Ui.SOFT:Ui.SURFACE,14));item.addView(Ui.text(a,key,10,Ui.MUTED));TextView value=Ui.text(a,key.equals("코덱")?codecName(content):content,spec?14:12,Ui.INK);value.setTextIsSelectable(true);value.setPadding(0,Ui.dp(a,7),0,0);if(spec)Ui.lines(value,2);item.addView(value);return item;}
    private static String codecName(String mime){return switch(mime){case "audio/flac"->"FLAC";case "audio/wav"->"WAV / PCM";case "audio/raw"->"PCM";case "audio/mpeg"->"MP3";case "audio/mp4a-latm"->"AAC";case "audio/alac"->"ALAC";case "audio/opus"->"Opus";case "audio/vorbis"->"Vorbis";default->mime;};}
    private static final class Borrowed extends MediaDataSource {private final MediaDataSource source;Borrowed(MediaDataSource source){this.source=source;}public int readAt(long p,byte[] b,int o,int n)throws IOException{return source.readAt(p,b,o,n);}public long getSize()throws IOException{return source.getSize();}public void close(){}}
    private static final class LocalSource extends MediaDataSource {private final android.content.res.AssetFileDescriptor asset;private final FileInputStream stream;private final java.nio.channels.FileChannel channel;private final long start,size;LocalSource(Context c,Uri uri)throws IOException{asset=c.getContentResolver().openAssetFileDescriptor(uri,"r");if(asset==null)throw new FileNotFoundException();start=asset.getStartOffset();size=asset.getLength()>=0?asset.getLength():asset.getParcelFileDescriptor().getStatSize();stream=new FileInputStream(asset.getFileDescriptor());channel=stream.getChannel();}public long getSize(){return size;}public int readAt(long position,byte[] buffer,int offset,int count)throws IOException{if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();if(count==0)return 0;if(position>=size)return -1;return channel.read(java.nio.ByteBuffer.wrap(buffer,offset,(int)Math.min(count,size-position)),start+position);}public void close()throws IOException{try{stream.close();}finally{asset.close();}}}
}
